INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r002', 'Le Petit Prince', 'Antoine de Saint-Exupéry', '1943', 'On peut également penser au Petit Prince d’Antoine de Saint-Exupéry, dans lequel le personnage principal voyage de planète en planète et découvre différentes façons de penser et de vivre.', 'Cette référence montre que la découverte de l’autre peut conduire à mieux comprendre le monde mais aussi à mieux se comprendre soi-même.', 'Le Renard : « On ne voit bien qu’avec le cœur. »', 'https://fr.wikiquote.org/wiki/Le_Petit_Prince', 'Le Petit Prince – Antoine de Saint-Exupéry (1943)', 'On peut également penser au Petit Prince d’Antoine de Saint-Exupéry, dans lequel le personnage principal voyage de planète en planète et découvre différentes façons de penser et de vivre. Cette référence montre que la découverte de l’autre peut conduire à mieux comprendre le monde mais aussi à mieux se comprendre soi-même.', 'voyage, découverte, enfance, relations humaines, apprentissage, ouverture aux autres, solitude, vieillesse / jeunesse', 'Feuil1', 2, 1);
