INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r003', 'Candide', 'Voltaire', '1759', 'On peut également penser à Candide de Voltaire, dans lequel le héros traverse de nombreux pays et affronte des situations qui remettent progressivement en cause ses certitudes.', 'Cette référence montre que les expériences vécues peuvent transformer notre manière de penser et nous conduire à porter un regard plus critique sur le monde.', 'Candide : « Il faut cultiver notre jardin. »', 'https://fr.wikiquote.org/wiki/Candide%2C_ou_l%27Optimisme', 'Candide – Voltaire (1759)', 'On peut également penser à Candide de Voltaire, dans lequel le héros traverse de nombreux pays et affronte des situations qui remettent progressivement en cause ses certitudes. Cette référence montre que les expériences vécues peuvent transformer notre manière de penser et nous conduire à porter un regard plus critique sur le monde.', 'voyage, expérience, apprentissage, société, esprit critique, évolution personnelle', 'Feuil1', 3, 2);
