INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r004', 'L’Odyssée', 'Homère', 'vers 700 av. J.-C.', 'On peut également penser à L’Odyssée d’Homère, dans laquelle Ulysse affronte de nombreuses épreuves avant de retrouver son foyer.', 'Cette référence montre que les difficultés rencontrées au cours d’un parcours peuvent mettre à l’épreuve un individu, mais aussi renforcer sa détermination et son identité.', 'Ulysse : « Je suis Ulysse, fils de Laërte. »', 'https://fr.wikisource.org/wiki/L%E2%80%99Odyss%C3%A9e_%28B%C3%A9rard%2C_Schmied%29/Tome_1/Invocation', 'L’Odyssée – Homère (vers 700 av. J.-C.)', 'On peut également penser à L’Odyssée d’Homère, dans laquelle Ulysse affronte de nombreuses épreuves avant de retrouver son foyer. Cette référence montre que les difficultés rencontrées au cours d’un parcours peuvent mettre à l’épreuve un individu, mais aussi renforcer sa détermination et son identité.', 'voyage, épreuves, courage, persévérance, identité, famille, héros', 'Feuil1', 4, 3);
