INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r005', 'Les Misérables', 'Victor Hugo', '1862', 'On peut également penser aux Misérables de Victor Hugo, dans lesquels Jean Valjean parvient progressivement à transformer son existence grâce aux rencontres et aux choix qu’il effectue.', 'Cette référence montre qu’un individu n’est pas nécessairement prisonnier de son passé et qu’il peut évoluer au contact des autres.', 'M. Madeleine (Jean Valjean) : « Il n’y a ni mauvaises herbes ni mauvais hommes. »', 'https://fr.wikiquote.org/wiki/Les_Mis%C3%A9rables', 'Les Misérables – Victor Hugo (1862)', 'On peut également penser aux Misérables de Victor Hugo, dans lesquels Jean Valjean parvient progressivement à transformer son existence grâce aux rencontres et aux choix qu’il effectue. Cette référence montre qu’un individu n’est pas nécessairement prisonnier de son passé et qu’il peut évoluer au contact des autres.', 'changement, société, solidarité, justice, relations humaines, seconde chance, justice / injustice, rêves', 'Feuil1', 5, 4);
