INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r006', 'Le Journal d’Anne Frank', 'Anne Frank', '1947', 'On peut également penser au Journal d’Anne Frank, dans lequel une adolescente met par écrit ses pensées, ses émotions et son quotidien alors qu’elle vit cachée pendant la Seconde Guerre mondiale.', 'Cette référence montre que l’écriture peut aider à exprimer son vécu tout en laissant un témoignage destiné aux générations futures.', 'Anne Frank : « Je veux continuer à vivre, même après ma mort ! »', 'https://catalogue.bnf.fr/ark:/12148/cb476803181', 'Le Journal d’Anne Frank – Anne Frank (1947)', 'On peut également penser au Journal d’Anne Frank, dans lequel une adolescente met par écrit ses pensées, ses émotions et son quotidien alors qu’elle vit cachée pendant la Seconde Guerre mondiale. Cette référence montre que l’écriture peut aider à exprimer son vécu tout en laissant un témoignage destiné aux générations futures.', 'écriture, mémoire, témoignage, adolescence, guerre, émotions', 'Feuil1', 6, 5);
