INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r007', 'Germinal', 'Émile Zola', '1885', 'On peut également penser à Germinal d’Émile Zola, dans lequel les conditions de vie difficiles des mineurs mettent en lumière les inégalités et les injustices sociales.', 'Cette référence montre que la littérature peut rendre visibles certaines réalités et amener le lecteur à réfléchir au fonctionnement de la société.', 'Maheu : « Nous voulons seulement la justice, nous sommes las de crever de faim. »', 'https://fr.wikiquote.org/wiki/Germinal_%28roman%29', 'Germinal – Émile Zola (1885)', 'On peut également penser à Germinal d’Émile Zola, dans lequel les conditions de vie difficiles des mineurs mettent en lumière les inégalités et les injustices sociales. Cette référence montre que la littérature peut rendre visibles certaines réalités et amener le lecteur à réfléchir au fonctionnement de la société.', 'société, injustice, travail, pauvreté, solidarité, littérature engagée, condition humaine, révolte, technologies', 'Feuil1', 7, 6);
