INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r008', 'Antigone', 'Sophocle', '441 av. J.-C.', 'On peut également penser à Antigone de Sophocle, dans laquelle l’héroïne choisit de défendre ses convictions malgré l’interdiction imposée par Créon.', 'Cette référence montre que l’attachement à ses valeurs peut conduire un individu à s’opposer à l’autorité et à assumer les conséquences de ses choix.', 'Antigone : « Je suis née non pour une haine mutuelle, mais pour un mutuel amour. »', 'https://fr.wikiquote.org/wiki/Sophocle', 'Antigone – Sophocle (441 av. J.-C.)', 'On peut également penser à Antigone de Sophocle, dans laquelle l’héroïne choisit de défendre ses convictions malgré l’interdiction imposée par Créon. Cette référence montre que l’attachement à ses valeurs peut conduire un individu à s’opposer à l’autorité et à assumer les conséquences de ses choix.', 'liberté, valeurs, autorité, choix, courage, désobéissance', 'Feuil1', 8, 7);
