INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r009', 'Les Fables', 'Jean de La Fontaine', '1668', 'On peut également penser aux Fables de La Fontaine, dans lesquelles les comportements humains sont représentés à travers des animaux et des situations souvent symboliques.', 'Cette référence montre que la littérature peut divertir tout en invitant le lecteur à réfléchir sur les défauts, les qualités et les rapports entre les individus.', 'Narrateur : « La raison du plus fort est toujours la meilleure. »', 'https://fr.wikisource.org/wiki/Les_Fables_de_La_Fontaine', 'Les Fables – Jean de La Fontaine (1668)', 'On peut également penser aux Fables de La Fontaine, dans lesquelles les comportements humains sont représentés à travers des animaux et des situations souvent symboliques. Cette référence montre que la littérature peut divertir tout en invitant le lecteur à réfléchir sur les défauts, les qualités et les rapports entre les individus.', 'éducation, morale, société, comportements humains, pouvoir, littérature', 'Feuil1', 9, 8);
