INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r010', 'Robinson Crusoé', 'Daniel Defoe', '1719', 'On peut également penser à Robinson Crusoé de Daniel Defoe, dans lequel un homme isolé sur une île doit apprendre à s’adapter à un environnement nouveau.', 'Cette référence montre que l’être humain peut développer de nouvelles ressources lorsqu’il est confronté à des difficultés ou à la solitude.', 'Robinson Crusoé (narrateur) : « J’avais de quoi manger et de quoi subvenir à mes besoins, que m’importait tout le reste ! »', 'https://fr.wikisource.org/wiki/Robinson_Cruso%C3%A9_%28Borel%29/26', 'Robinson Crusoé – Daniel Defoe (1719)', 'On peut également penser à Robinson Crusoé de Daniel Defoe, dans lequel un homme isolé sur une île doit apprendre à s’adapter à un environnement nouveau. Cette référence montre que l’être humain peut développer de nouvelles ressources lorsqu’il est confronté à des difficultés ou à la solitude.', 'solitude, adaptation, autonomie, nature, épreuve, survie', 'Feuil1', 10, 9);
