INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r011', 'Harry Potter et la Chambre des secrets', 'J. K. Rowling', '1998', 'On peut également penser à la série Harry Potter de J. K. Rowling, dans laquelle le héros grandit en affrontant des épreuves et en construisant des relations fondées sur l’amitié et la confiance.', 'Cette référence montre que les expériences et les liens avec les autres participent à la construction de l’individu.', 'Albus Dumbledore : « Ce sont nos choix, Harry, qui montrent ce que nous sommes vraiment. »', 'https://fr.wikiquote.org/wiki/Harry_Potter', 'Harry Potter et la Chambre des secrets – J. K. Rowling (1998)', 'On peut également penser à la série Harry Potter de J. K. Rowling, dans laquelle le héros grandit en affrontant des épreuves et en construisant des relations fondées sur l’amitié et la confiance. Cette référence montre que les expériences et les liens avec les autres participent à la construction de l’individu.', 'enfance, adolescence, amitié, courage, apprentissage, identité', 'Feuil1', 11, 10);
