INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r012', 'Le 3 mai 1808 à Madrid', 'Francisco de Goya', '1814', 'On peut également penser à l’œuvre Le 3 mai 1808 à Madrid, de Francisco de Goya (1814) : Dans la nuit du 2 au 3 mai 1808, les soldats français — en représailles à la révolte du 2 mai — exécutent les combattants espagnols faits prisonniers au cours de la bataille', NULL, 'Aucun locuteur : il s’agit d’une œuvre picturale.', NULL, 'Le 3 mai 1808 à Madrid – Francisco de Goya (1814)', 'Dans la nuit du 2 au 3 mai 1808, les soldats français — en représailles à la révolte du 2 mai — exécutent les combattants espagnols faits prisonniers au cours de la bataille', 'guerre', 'Feuil1', 12, 11);
INSERT INTO literary_reference_themes (reference_id, theme, position) VALUES ('literature-enriched-r012', 'guerre', 1);
INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r013', 'Guernica', 'Pablo Picasso', '1937', 'On peut également penser à l’œuvre Guernica, de Pablo Picasso (1937) : l’artiste ne représente pas de manière réaliste le bombardement de la ville espagnole, mais déforme les corps, les visages et les formes afin d’exprimer la violence et la souffrance provoquées par la guerre.', 'Cette référence montre que l’art ne se contente pas de reproduire le réel : il le transforme pour en proposer une interprétation et susciter une émotion chez le spectateur.', 'Aucun locuteur : il s’agit d’une œuvre picturale.', NULL, 'Guernica – Pablo Picasso (1937)', 'l’artiste ne représente pas de manière réaliste le bombardement de la ville espagnole, mais déforme les corps, les visages et les formes afin d’exprimer la violence et la souffrance provoquées par la guerre. Cette référence montre que l’art ne se contente pas de reproduire le réel : il le transforme pour en proposer une interprétation et susciter une émotion chez le spectateur.', 'art, guerre, violence, engagement, transformation du réel, émotion', 'Feuil1', 13, 12);
