INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r014', 'Les Nymphéas', 'Claude Monet', '1897', 'On peut également penser à l’œuvre Les Nymphéas, de Claude Monet (1897) : l’artiste ne cherche pas seulement à représenter un paysage, mais à restituer les variations de lumière, de couleur et d’atmosphère. Cette œuvre invite ainsi le spectateur à porter un regard nouveau sur une réalité pourtant ordinaire.', 'Cette référence montre que l’art peut transformer notre perception du réel en nous faisant voir autrement ce que nous pensions connaître.', 'Aucun locuteur : il s’agit d’une œuvre picturale.', NULL, 'Les Nymphéas – Claude Monet (1897)', 'l’artiste ne cherche pas seulement à représenter un paysage, mais à restituer les variations de lumière, de couleur et d’atmosphère. Cette œuvre invite ainsi le spectateur à porter un regard nouveau sur une réalité pourtant ordinaire. Cette référence montre que l’art peut transformer notre perception du réel en nous faisant voir autrement ce que nous pensions connaître.', 'art, beauté, regard, perception, nature, transformation du réel', 'Feuil1', 14, 13);
INSERT INTO literary_reference_themes (reference_id, theme, position) VALUES ('literature-enriched-r014', 'art', 1);
INSERT INTO literary_reference_themes (reference_id, theme, position) VALUES ('literature-enriched-r014', 'beauté', 2);
