INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r015', '« Comment Wang-Fô fut sauvé »', 'Marguerite Yourcenar', '1938', 'On peut également penser à l’œuvre « Comment Wang-Fô fut sauvé », de Marguerite Yourcenar (1938) : Dans « Comment Wang-Fô fut sauvé », le peintre transforme le réel par son art jusqu’à faire basculer le récit dans le merveilleux.', 'Cette référence montre que l’art ne se contente pas de reproduire le monde : il peut le recréer et offrir une échappée hors du réel.', 'Narrateur : « Le pavement de jade devenait singulièrement humide, mais Wang-Fô, absorbé dans sa peinture, ne s’apercevait pas qu’il travaillait assis dans l’eau. »', 'https://fr.wikiquote.org/wiki/Nouvelles_orientales', '« Comment Wang-Fô fut sauvé » – Marguerite Yourcenar (1938)', 'Dans « Comment Wang-Fô fut sauvé », le peintre transforme le réel par son art jusqu’à faire basculer le récit dans le merveilleux. Cette référence montre que l’art ne se contente pas de reproduire le monde : il peut le recréer et offrir une échappée hors du réel.', 'art, création, imagination, transformation du réel, beauté, liberté', 'Feuil1', 15, 14);
