INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r016', 'Évangile selon Matthieu', 'Matthieu', 'vers 85 apr. J.-C.', 'On peut également penser à la Passion du Christ, dans l’Évangile selon Matthieu, où les soldats romains humilient et tournent Jésus en dérision en le couronnant d’épines.', 'Cette référence montre que la moquerie peut devenir une forme de violence morale, destinée à rabaisser un individu et à porter atteinte à sa dignité.', 'Les soldats romains : « Salut, roi des Juifs ! »', 'https://www.aelf.org/bible/Mt/27', 'Évangile selon Matthieu – Matthieu (vers 85 apr. J.-C.)', 'On peut également penser à la Passion du Christ, dans l’Évangile selon Matthieu, où les soldats romains humilient et tournent Jésus en dérision en le couronnant d’épines. Cette référence montre que la moquerie peut devenir une forme de violence morale, destinée à rabaisser un individu et à porter atteinte à sa dignité.', 'rire, moquerie, humiliation, violence, pouvoir, dignité, religion', 'Feuil1', 16, 15);
