INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r017', 'Le Nom de la rose (film)', 'Jean-Jacques Annaud', '1986', 'On peut également penser à l’œuvre Le Nom de la rose (film), de Jean-Jacques Annaud (1986) : Dans Le Nom de la rose, Jorge de Burgos considère le rire comme une menace pour la foi et l’autorité, car il peut libérer les hommes de la peur et remettre en cause ce qui est présenté comme sacré.', 'Cette référence montre que le rire peut devenir un instrument de liberté et de contestation.', 'Jorge de Burgos : « Le rire tue la peur, et sans la peur il n’est pas de foi. »', 'https://fr.wikiquote.org/wiki/Le_Nom_de_la_rose_%28film%29', 'Le Nom de la rose (film) – Jean-Jacques Annaud (1986)', 'Dans Le Nom de la rose, Jorge de Burgos considère le rire comme une menace pour la foi et l’autorité, car il peut libérer les hommes de la peur et remettre en cause ce qui est présenté comme sacré. Cette référence montre que le rire peut devenir un instrument de liberté et de contestation.', 'rire, peur, pouvoir, religion, liberté, esprit critique, savoir', 'Feuil1', 17, 16);
