INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r018', 'Princesse Mononoké', 'Hayao Miyazaki', '1997', 'On peut également penser à l’œuvre Princesse Mononoké, de Hayao Miyazaki (1997) : La cité des forges assure la prospérité des humains mais détruit progressivement la forêt.', 'Cette référence montre que le progrès peut améliorer la vie humaine tout en menaçant l’environnement lorsqu’aucune limite n’est posée.', 'Narrateur : « Hommes et bêtes vivaient en harmonie. »', 'https://fr.wikiquote.org/wiki/Princesse_Mononok%C3%A9', 'Princesse Mononoké – Hayao Miyazaki (1997)', 'La cité des forges assure la prospérité des humains mais détruit progressivement la forêt. Cette référence montre que le progrès peut améliorer la vie humaine tout en menaçant l’environnement lorsqu’aucune limite n’est posée.', 'nature, progrès, environnement, développement durable, responsabilité', 'Feuil1', 18, 17);
