INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r019', 'Princesse Mononoké', 'Hayao Miyazaki', '1997', 'On peut également penser à l’œuvre Princesse Mononoké, de Hayao Miyazaki (1997) : Le dieu sanglier Nago devient un démon après avoir été blessé par les humains.', 'Cette référence montre que la haine peut consumer celui qui l’éprouve et nourrir un cycle de violence.', 'Ashitaka : « La colère et la peur décuplent la force du mal. »', 'https://fr.wikiquote.org/wiki/Princesse_Mononok%C3%A9', 'Princesse Mononoké – Hayao Miyazaki (1997)', 'Le dieu sanglier Nago devient un démon après avoir été blessé par les humains. Cette référence montre que la haine peut consumer celui qui l’éprouve et nourrir un cycle de violence.', 'haine, violence, vengeance, colère, guerre, paix', 'Feuil1', 19, 18);
