INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r020', 'Princesse Mononoké', 'Hayao Miyazaki', '1997', 'On peut également penser à l’œuvre Princesse Mononoké, de Hayao Miyazaki (1997) : Dame Eboshi protège les exclus tout en participant à la destruction de la forêt.', 'Cette référence montre qu’un individu peut accomplir à la fois des actions généreuses et destructrices, ce qui interdit une vision trop simple du bien et du mal.', 'Dame Eboshi : « Les hommes sont beaucoup plus dangereux que les dieux de la forêt. »', 'https://fr.wikiquote.org/wiki/Princesse_Mononok%C3%A9', 'Princesse Mononoké – Hayao Miyazaki (1997)', 'Dame Eboshi protège les exclus tout en participant à la destruction de la forêt. Cette référence montre qu’un individu peut accomplir à la fois des actions généreuses et destructrices, ce qui interdit une vision trop simple du bien et du mal.', 'bien, mal, morale, responsabilité, jugement, complexité humaine', 'Feuil1', 20, 19);
