INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r021', 'Princesse Mononoké', 'Hayao Miyazaki', '1997', 'On peut également penser à l’œuvre Princesse Mononoké, de Hayao Miyazaki (1997) : San est humaine mais a été élevée par les loups et se considère comme l’une des leurs.', 'Cette référence montre que l’identité se construit aussi par l’éducation, les liens affectifs et le sentiment d’appartenance.', 'Moro : « San est ma fille, ma tribu est la sienne. »', 'https://fr.wikiquote.org/wiki/Princesse_Mononok%C3%A9', 'Princesse Mononoké – Hayao Miyazaki (1997)', 'San est humaine mais a été élevée par les loups et se considère comme l’une des leurs. Cette référence montre que l’identité se construit aussi par l’éducation, les liens affectifs et le sentiment d’appartenance.', 'identité, éducation, famille, appartenance, différence', 'Feuil1', 21, 20);
