INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r022', 'Princesse Mononoké', 'Hayao Miyazaki', '1997', 'On peut également penser à l’œuvre Princesse Mononoké, de Hayao Miyazaki (1997) : Dame Eboshi dirige une communauté où elle donne du travail et une place sociale à des femmes marginalisées et à des malades.', 'Cette référence montre que l’autonomie économique et l’intégration peuvent rendre leur dignité aux personnes exclues.', 'Ashitaka : « On dit que femmes heureuses font bon village. »', 'https://fr.wikiquote.org/wiki/Princesse_Mononok%C3%A9', 'Princesse Mononoké – Hayao Miyazaki (1997)', 'Dame Eboshi dirige une communauté où elle donne du travail et une place sociale à des femmes marginalisées et à des malades. Cette référence montre que l’autonomie économique et l’intégration peuvent rendre leur dignité aux personnes exclues.', 'femmes, société, travail, émancipation, exclusion, solidarité', 'Feuil1', 22, 21);
