INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r024', 'Princesse Mononoké', 'Hayao Miyazaki', '1997', 'On peut également penser à l’œuvre Princesse Mononoké, de Hayao Miyazaki (1997) : San s’oppose aux humains qui détruisent la forêt et va jusqu’à attaquer la cité des forges.', 'Cette référence montre que le sentiment d’injustice peut conduire à la révolte, mais aussi à l’escalade de la violence.', 'San : « Ashitaka, je t’aime beaucoup mais je ne peux pas pardonner ce que les humains ont fait. »', 'https://fr.wikiquote.org/wiki/Princesse_Mononok%C3%A9', 'Princesse Mononoké – Hayao Miyazaki (1997)', 'San s’oppose aux humains qui détruisent la forêt et va jusqu’à attaquer la cité des forges. Cette référence montre que le sentiment d’injustice peut conduire à la révolte, mais aussi à l’escalade de la violence.', 'révolte, injustice, engagement, violence, résistance', 'Feuil1', 24, 23);
