INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r042', 'Mon voisin Totoro', 'Hayao Miyazaki', '1988', 'On peut également penser à l’œuvre Mon voisin Totoro, de Hayao Miyazaki (1988) : Satsuki et Mei traversent l’épreuve de l’hospitalisation de leur mère tout en restant très liées à leur père et l’une à l’autre.', 'Cette référence montre que les liens familiaux apportent sécurité et soutien face à l’incertitude.', 'Satsuki Kusakabe : « Qu’allons-nous devenir, Mei et moi, si Maman meurt ? »', 'https://fr.wikiquote.org/wiki/Mon_voisin_Totoro', 'Mon voisin Totoro – Hayao Miyazaki (1988)', 'Satsuki et Mei traversent l’épreuve de l’hospitalisation de leur mère tout en restant très liées à leur père et l’une à l’autre. Cette référence montre que les liens familiaux apportent sécurité et soutien face à l’incertitude.', 'famille, enfance, maladie, solidarité, amour', 'Feuil1', 42, 41);
