INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r043', 'Mon voisin Totoro', 'Hayao Miyazaki', '1988', 'On peut également penser à l’œuvre Mon voisin Totoro, de Hayao Miyazaki (1988) : Les enfants trouvent de la joie dans la nature, le jeu et la présence de Totoro malgré leurs inquiétudes familiales.', 'Cette référence montre que le bonheur peut naître de moments simples et de la capacité à s’émerveiller.', 'Satsuki Kusakabe : « Nous avons vu Totoro ! Nous l’avons vu toutes les deux. »', 'https://fr.wikiquote.org/wiki/Mon_voisin_Totoro', 'Mon voisin Totoro – Hayao Miyazaki (1988)', 'Les enfants trouvent de la joie dans la nature, le jeu et la présence de Totoro malgré leurs inquiétudes familiales. Cette référence montre que le bonheur peut naître de moments simples et de la capacité à s’émerveiller.', 'bonheur, enfance, nature, imagination, simplicité', 'Feuil1', 43, 42);
