INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r044', 'Le Château dans le ciel', 'Hayao Miyazaki', '1986', 'On peut également penser à l’œuvre Le Château dans le ciel, de Hayao Miyazaki (1986) : Muska veut utiliser la technologie de Laputa pour dominer les autres.', 'Cette référence montre que la puissance technique devient dangereuse lorsqu’elle est placée au service d’une volonté de pouvoir absolu.', 'Sheeta : « À quoi bon se proclamer roi une fois que son royaume est anéanti ? »', 'https://fr.wikiquote.org/wiki/Le_Ch%C3%A2teau_dans_le_ciel', 'Le Château dans le ciel – Hayao Miyazaki (1986)', 'Muska veut utiliser la technologie de Laputa pour dominer les autres. Cette référence montre que la puissance technique devient dangereuse lorsqu’elle est placée au service d’une volonté de pouvoir absolu.', 'pouvoir, technologie, science-fiction, domination, morale', 'Feuil1', 44, 43);
