INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r045', 'Le Château dans le ciel', 'Hayao Miyazaki', '1986', 'On peut également penser à l’œuvre Le Château dans le ciel, de Hayao Miyazaki (1986) : Pazu et Sheeta partent à la recherche de Laputa tout en étant poursuivis par l’armée et les pirates.', 'Cette référence montre que l’aventure confronte les personnages à l’inconnu et favorise courage, entraide et dépassement de soi.', 'Pazu : « Je vais me fabriquer un véritable avion et je prouverai à tout le monde que Laputa existe ! »', 'https://fr.wikiquote.org/wiki/Le_Ch%C3%A2teau_dans_le_ciel', 'Le Château dans le ciel – Hayao Miyazaki (1986)', 'Pazu et Sheeta partent à la recherche de Laputa tout en étant poursuivis par l’armée et les pirates. Cette référence montre que l’aventure confronte les personnages à l’inconnu et favorise courage, entraide et dépassement de soi.', 'aventure, voyage, courage, amitié, découverte', 'Feuil1', 45, 44);
