INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r046', 'Nausicaä de la Vallée du Vent', 'Hayao Miyazaki', '1984', 'On peut également penser à l’œuvre Nausicaä de la Vallée du Vent, de Hayao Miyazaki (1984) : Nausicaä cherche à comprendre les différents camps et à empêcher le massacre plutôt qu’à vaincre un ennemi.', 'Cette référence montre que l’héroïsme peut reposer sur l’empathie, la médiation et le sacrifice plutôt que sur la force.', 'Nausicaä : « La grandeur d’une âme est déterminée par la profondeur de ses souffrances. »', 'https://fr.wikiquote.org/wiki/Nausica%C3%A4_de_la_Vall%C3%A9e_du_Vent_%28film_d%27animation%29', 'Nausicaä de la Vallée du Vent – Hayao Miyazaki (1984)', 'Nausicaä cherche à comprendre les différents camps et à empêcher le massacre plutôt qu’à vaincre un ennemi. Cette référence montre que l’héroïsme peut reposer sur l’empathie, la médiation et le sacrifice plutôt que sur la force.', 'héros, paix, courage, sacrifice, empathie, guerre', 'Feuil1', 46, 45);
