INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r047', 'Nausicaä de la Vallée du Vent', 'Hayao Miyazaki', '1984', 'On peut également penser à l’œuvre Nausicaä de la Vallée du Vent, de Hayao Miyazaki (1984) : Le monde est envahi par une forêt toxique née après une catastrophe ancienne, mais Nausicaä découvre qu’elle participe aussi à la purification de la planète.', 'Cette référence montre que la nature peut être plus complexe que l’image hostile que l’homme s’en fait.', 'Nausicaä : « Quand l’homme rompt l’équilibre du monde, la forêt fait d’énormes sacrifices pour rétablir cet équilibre. »', 'https://fr.wikiquote.org/wiki/Nausica%C3%A4_de_la_Vall%C3%A9e_du_Vent_%28film_d%27animation%29', 'Nausicaä de la Vallée du Vent – Hayao Miyazaki (1984)', 'Le monde est envahi par une forêt toxique née après une catastrophe ancienne, mais Nausicaä découvre qu’elle participe aussi à la purification de la planète. Cette référence montre que la nature peut être plus complexe que l’image hostile que l’homme s’en fait.', 'nature, science-fiction, environnement, technologie, perception', 'Feuil1', 47, 46);
