INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r048', 'Le vent se lève', 'Hayao Miyazaki', '2013', 'On peut également penser à l’œuvre Le vent se lève, de Hayao Miyazaki (2013) : Jirō cherche à créer des avions beaux et performants tout en sachant qu’ils seront utilisés pour la guerre.', 'Cette référence interroge la responsabilité du créateur lorsque son œuvre peut être détournée vers des fins destructrices.', 'Jirō (citant Paul Valéry) : « Le vent se lève… il faut tenter de vivre ! »', 'https://fr.wikiquote.org/wiki/Le_vent_se_l%C3%A8ve_%28film%2C_2013%29', 'Le vent se lève – Hayao Miyazaki (2013)', 'Jirō cherche à créer des avions beaux et performants tout en sachant qu’ils seront utilisés pour la guerre. Cette référence interroge la responsabilité du créateur lorsque son œuvre peut être détournée vers des fins destructrices.', 'art, technologie, morale, guerre, responsabilité, création', 'Feuil1', 48, 47);
