INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r049', 'Le vent se lève', 'Hayao Miyazaki', '2013', 'On peut également penser à l’œuvre Le vent se lève, de Hayao Miyazaki (2013) : Jirō rencontre Caproni dans des séquences oniriques où il imagine l’avenir de l’aviation.', 'Cette référence montre que le rêve peut nourrir l’ambition, la création et la capacité de se projeter au-delà du réel immédiat.', 'Caproni (citant Paul Valéry) : « Le vent se lève… il faut tenter de vivre ! »', 'https://fr.wikiquote.org/wiki/Le_vent_se_l%C3%A8ve_%28film%2C_2013%29', 'Le vent se lève – Hayao Miyazaki (2013)', 'Jirō rencontre Caproni dans des séquences oniriques où il imagine l’avenir de l’aviation. Cette référence montre que le rêve peut nourrir l’ambition, la création et la capacité de se projeter au-delà du réel immédiat.', 'rêves, imagination, ambition, art, création', 'Feuil1', 49, 48);
