INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r050', 'Si tu tends l’oreille', 'Yoshifumi Kondō', '1995', 'On peut également penser à l’œuvre Si tu tends l’oreille, de Yoshifumi Kondō (1995) : Shizuku se lance dans l’écriture d’un récit inspiré par une statuette de chat.', 'Cette référence montre que la fiction peut devenir un moyen de création mais aussi de découverte de soi et de ses propres capacités.', 'Shizuku : « J’ai écrit une histoire, alors je vous l’ai apportée. »', 'https://fr.wikiquote.org/wiki/Si_tu_tends_l%27oreille', 'Si tu tends l’oreille – Yoshifumi Kondō (1995)', 'Shizuku se lance dans l’écriture d’un récit inspiré par une statuette de chat. Cette référence montre que la fiction peut devenir un moyen de création mais aussi de découverte de soi et de ses propres capacités.', 'fiction, art, écriture, imagination, identité, jeunesse', 'Feuil1', 50, 49);
