INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r051', 'Souvenirs goutte à goutte', 'Isao Takahata', '1991', 'On peut également penser à l’œuvre Souvenirs goutte à goutte, de Isao Takahata (1991) : Taeko adulte se remémore régulièrement l’enfant qu’elle était.', 'Cette référence montre que le passé continue d’influencer l’identité et les décisions du présent.', 'Taeko adulte : « Peut-être que tous ces souvenirs me reviennent parce que je cherche de nouveau à prendre mon envol. »', 'https://fr.wikiquote.org/wiki/Souvenirs_goutte_%C3%A0_goutte', 'Souvenirs goutte à goutte – Isao Takahata (1991)', 'Taeko adulte se remémore régulièrement l’enfant qu’elle était. Cette référence montre que le passé continue d’influencer l’identité et les décisions du présent.', 'temps, mémoire, enfance, identité, choix, passé', 'Feuil1', 51, 50);
