INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r052', 'Kiki la petite sorcière', 'Hayao Miyazaki', '1989', 'On peut également penser à l’œuvre Kiki la petite sorcière, de Hayao Miyazaki (1989) : Kiki quitte sa famille pour vivre seule et exercer son métier de sorcière.', 'Cette référence montre que l’autonomie se construit par l’expérience, le travail, les rencontres et parfois le doute.', 'Kiki : « Pour devenir une vraie sorcière, je dois pouvoir tenir un an loin de la maison. »', 'https://fr.wikiquote.org/wiki/Kiki_la_petite_sorci%C3%A8re', 'Kiki la petite sorcière – Hayao Miyazaki (1989)', 'Kiki quitte sa famille pour vivre seule et exercer son métier de sorcière. Cette référence montre que l’autonomie se construit par l’expérience, le travail, les rencontres et parfois le doute.', 'identité, autonomie, jeunesse, travail, solitude, apprentissage', 'Feuil1', 52, 51);
