INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r053', 'Porco Rosso', 'Hayao Miyazaki', '1992', 'On peut également penser à l’œuvre Porco Rosso, de Hayao Miyazaki (1992) : Porco choisit une existence indépendante de pilote et porte littéralement un visage de cochon.', 'Cette référence permet d’interroger le refus des normes, la liberté individuelle et la manière dont un personnage construit son identité après la guerre.', 'Porco Rosso : « Je préfère encore être un cochon décadent qu’un fasciste. »', 'https://fr.wikiquote.org/wiki/Porco_Rosso', 'Porco Rosso – Hayao Miyazaki (1992)', 'Porco choisit une existence indépendante de pilote et porte littéralement un visage de cochon. Cette référence permet d’interroger le refus des normes, la liberté individuelle et la manière dont un personnage construit son identité après la guerre.', 'liberté, identité, guerre, solitude, héros, société', 'Feuil1', 53, 52);
