INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r054', 'Arrietty, le petit monde des chapardeurs', 'Hiromasa Yonebayashi', '2010', 'On peut également penser à l’œuvre Arrietty, le petit monde des chapardeurs, de Hiromasa Yonebayashi (2010) : Arrietty appartient à un peuple minuscule qui doit vivre caché des humains.', 'Cette référence montre comment la différence peut produire peur, isolement et méfiance, mais aussi susciter la rencontre et l’amitié.', 'Arrietty : « Les humains sont dangereux pour nous. Ce sont mes parents qui le disent. »', 'https://fr.wikiquote.org/wiki/Arrietty_%3A_Le_Petit_Monde_des_Chapardeurs', 'Arrietty, le petit monde des chapardeurs – Hiromasa Yonebayashi (2010)', 'Arrietty appartient à un peuple minuscule qui doit vivre caché des humains. Cette référence montre comment la différence peut produire peur, isolement et méfiance, mais aussi susciter la rencontre et l’amitié.', 'différence, solitude, identité, amitié, société, peur', 'Feuil1', 54, 53);
