INSERT INTO literary_references (domain_id, source_id, id, title, creator, publication_date, reference_text, analysis_text, excerpt_text, excerpt_source, source_reference, source_text, source_themes, sheet_name, source_row, position) VALUES ('references', 'references-crpe-enrichies-word-ghibli', 'literature-enriched-r055', '1984', 'George Orwell', '1949', 'On peut également penser à l’œuvre 1984, de George Orwell.', 'Cette référence peut être mobilisée pour montrer que la littérature et les arts permettent d’observer les règles, les inégalités et les tensions qui structurent une société.', 'Slogan du Parti : « Big Brother vous regarde. »', 'https://fr.wikiquote.org/wiki/1984_(roman)', '1984 – George Orwell (1949)', 'On peut également penser à l’œuvre 1984, de George Orwell. Cette référence peut être mobilisée pour montrer que la littérature et les arts permettent d’observer les règles, les inégalités et les tensions qui structurent une société.', 'société, science-fiction, ville', 'Feuil1', 55, 54);
